def factory(name,bases,ns): return type(name,bases,ns)
class C(metaclass=factory):
 def f(self): return __class__
print(C().f() is C,type(C) is type)

class Factory:
 def __call__(self,name,bases,ns,*,tag):
  print(name,tag is value,ns["ns"] is ns)
  return ns
value=[7]
class C(metaclass=Factory(),tag=value): ns=locals()
print(C["ns"] is C)

class Factory:
 def __prepare__(self,name,bases,*,tag):
  print("prepare",name,tag)
  return {"x":7}
 def __call__(self,name,bases,ns,*,tag):
  print("call",ns["x"],tag)
  return ns["x"]
class C(metaclass=Factory(),tag=9):
 print(x)
print(C)

class Factory:
 def __getattribute__(self,name):
  print(name)
  raise AttributeError(name)
 def __call__(self,name,bases,ns): return 7
class C(metaclass=Factory()): print("body")
print(C)

class D:
 def __get__(self,obj,owner):
  print("prepare lookup")
  return lambda name,bases: {}
class Factory:
 __prepare__=D()
 def __call__(self,name,bases,ns): return 7
class C(metaclass=Factory()): pass
print(C)

def prepare(name,bases):
 print("prepare")
 raise AttributeError("original")
def factory(name,bases,ns): print("never")
factory.__prepare__=prepare
class C(metaclass=factory): print("never")

def factory(name,bases,ns):
 print("factory")
 raise ValueError("original")
class C(metaclass=factory): print("body")

def factory(name,bases,ns): return 7
factory.__prepare__=lambda name,bases: 7
class C(metaclass=factory): print("never")

class Factory:
 def __prepare__(self,name,bases): print("prepare"); return {}
class C(metaclass=Factory()): print("body")

class Factory:
 def __new__(factory,name,bases,ns):
  print(name,ns["x"])
  return 7
class C(metaclass=Factory): x=9
print(C)

class Factory:
 @classmethod
 def __prepare__(factory,name,bases): print("prepare"); return {"x":7}
 def __init__(self,name,bases,ns): self.value=ns["x"]
class C(metaclass=Factory): print(x)
print(type(C) is Factory,C.value)

