class Factory:
 def __new__(cls,*args):
  if args: return args[2]["x"]
  return object.__new__(cls)
 @classmethod
 def __prepare__(cls,name,bases):
  print(name,bases[0] is base)
  return {"x":7}
base=Factory()
class C(base): print(x)
print(C)

